"""SparTree (Syntax-aware Parse Tree) representation for program reduction."""

from __future__ import annotations
from enum import Enum
from typing import List, Optional
import copy

from reduction.token import Token


class NodeType(Enum):
    """Types of nodes in the SparTree, corresponding to grammar quantifiers."""
    KLEENE_STAR = "kleene_star"    # Zero or more repetitions
    KLEENE_PLUS = "kleene_plus"    # One or more repetitions
    OPTIONAL = "optional"          # Zero or one occurrence
    REGULAR = "regular"            # Exactly one occurrence (sequence/alternation)
    TOKEN = "token"                # Leaf node holding a token


class SparTreeNode:
    """A node in the SparTree parse tree.

    The SparTree is the core data structure for syntax-aware reduction.
    Each node corresponds to a grammar rule, and the tree structure
    reflects the syntactic structure of the program. Nodes can be
    marked as 'deleted' to represent program variants with fewer tokens.
    """

    def __init__(
        self,
        rule_name: str,
        node_type: NodeType,
        children: Optional[List['SparTreeNode']] = None,
        token: Optional[Token] = None,
    ):
        self.rule_name = rule_name
        self.node_type = node_type
        self.children: List[SparTreeNode] = children if children is not None else []
        self.token = token
        self.deleted: bool = False

    def token_count(self) -> int:
        """Count non-deleted token descendants."""
        if self.deleted:
            return 0
        if self.node_type == NodeType.TOKEN:
            return 1
        return sum(child.token_count() for child in self.children)

    def tokens(self) -> List[Token]:
        """Get non-deleted tokens in order (left-to-right traversal)."""
        if self.deleted:
            return []
        if self.node_type == NodeType.TOKEN and self.token is not None:
            return [self.token]
        result = []
        for child in self.children:
            result.extend(child.tokens())
        return result

    def to_source(self) -> str:
        """Reconstruct source code from non-deleted tokens.

        Rebuilds the source text by placing tokens at their original
        line/column positions where possible.
        """
        tokens = self.tokens()
        if not tokens:
            return ""

        # Group tokens by line
        lines_dict: dict[int, list[Token]] = {}
        for tok in tokens:
            if tok.type == 'NEWLINE':
                continue
            if tok.line not in lines_dict:
                lines_dict[tok.line] = []
            lines_dict[tok.line].append(tok)

        if not lines_dict:
            return ""

        # Reconstruct lines
        result_lines = []
        for line_num in sorted(lines_dict.keys()):
            line_tokens = sorted(lines_dict[line_num], key=lambda t: t.col)
            line_str = ""
            current_col = 0
            for tok in line_tokens:
                if tok.type == 'INDENT':
                    line_str += tok.value
                    current_col = len(tok.value)
                else:
                    if tok.col > current_col:
                        line_str += " " * (tok.col - current_col)
                    elif current_col > 0 and line_str and not line_str.endswith(' '):
                        line_str += " "
                    line_str += tok.value
                    current_col = tok.col + len(tok.value)
            result_lines.append(line_str)

        return "\n".join(result_lines) + "\n"

    def clone(self) -> 'SparTreeNode':
        """Create a deep copy of this node and all descendants."""
        return copy.deepcopy(self)

    def all_nodes(self) -> List['SparTreeNode']:
        """Get all non-deleted descendant nodes (including self) in pre-order."""
        if self.deleted:
            return []
        result = [self]
        for child in self.children:
            result.extend(child.all_nodes())
        return result

    def delete(self) -> None:
        """Mark this node and all children as deleted."""
        self.deleted = True
        for child in self.children:
            child.delete()

    def undelete(self) -> None:
        """Unmark deletion on this node and all children."""
        self.deleted = False
        for child in self.children:
            child.undelete()

    def is_deletable(self) -> bool:
        """Determine if this node can be deleted per grammar rules.

        Deletion rules:
        - KLEENE_STAR children: always deletable (zero or more)
        - KLEENE_PLUS children: deletable if at least one sibling remains
        - OPTIONAL children: always deletable
        - REGULAR: depends on parent context (conservative: not deletable)
        - TOKEN: leaf nodes follow parent's deletability
        """
        if self.node_type == NodeType.KLEENE_STAR:
            return True
        if self.node_type == NodeType.OPTIONAL:
            return True
        if self.node_type == NodeType.KLEENE_PLUS:
            # Can be deleted if it's a child of a Kleene-star/plus parent
            # and siblings remain. Conservative: return True since the
            # parent manages the constraint.
            return True
        if self.node_type == NodeType.TOKEN:
            return False
        # REGULAR nodes are generally not independently deletable
        return False

    def __repr__(self):
        if self.deleted:
            return f"SparTreeNode({self.rule_name!r}, DELETED)"
        if self.node_type == NodeType.TOKEN:
            return f"SparTreeNode(TOKEN, {self.token!r})"
        return f"SparTreeNode({self.rule_name!r}, {self.node_type.value}, children={len(self.children)})"

"""Perses syntax-guided program reducer."""

from __future__ import annotations

from dataclasses import dataclass
import heapq
from itertools import count

from reduction.grammar import Grammar
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import NodeType, SparTreeNode


QUANTIFIED_NODE_TYPES = {
    NodeType.KLEENE_STAR,
    NodeType.KLEENE_PLUS,
    NodeType.OPTIONAL,
}


@dataclass(frozen=True)
class NodeEntry:
    """Tree node plus its stable path information."""

    path: tuple[int, ...]
    parent_path: tuple[int, ...] | None
    child_index: int | None
    node: SparTreeNode


class PersesReducer(AbstractReducer):
    """Syntax-guided reducer inspired by Perses.

    The reducer repeatedly scans the tree in descending subtree-size order. It
    applies two reduction strategies:

    1. ddmin-style deletion on quantified children (root blocks, statement
       blocks, repeated clause lists),
    2. replacement of a node by a smaller compatible descendant using the same
       grammar rule name.
    """

    def __init__(self, grammar: Grammar):
        self.grammar = grammar
        self.parser = Parser(grammar)

    @property
    def name(self) -> str:
        return "perses"

    def reduce(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        current = tree

        while True:
            updated = self._reduce_once(current, tester)
            if updated is current:
                return current
            current = updated

    def _reduce_once(
        self,
        tree: SparTreeNode,
        tester: PropertyTester,
    ) -> SparTreeNode:
        heap: list[tuple[int, int, int, NodeEntry]] = []
        serial = count()

        for entry in self._walk_entries(tree):
            size = entry.node.token_count()
            if size <= 0:
                continue
            heapq.heappush(
                heap,
                (-size, len(entry.path), next(serial), entry),
            )

        while heap:
            _, _, _, entry = heapq.heappop(heap)
            node = self._node_at_path(tree, entry.path)
            if node is None or node.token_count() == 0:
                continue

            if entry.path and node.node_type in (NodeType.OPTIONAL, NodeType.KLEENE_STAR):
                candidate = self._try_delete_quantified_node(tree, entry, tester)
                if candidate is not None:
                    return candidate

            if node.node_type in QUANTIFIED_NODE_TYPES:
                candidate = self._ddmin_quantified_children(tree, entry.path, tester)
                if candidate is not None:
                    return candidate

            if node.node_type == NodeType.REGULAR:
                candidate = self._replace_with_descendant(tree, entry.path, tester)
                if candidate is not None:
                    return candidate

        return tree

    def _try_delete_quantified_node(
        self,
        tree: SparTreeNode,
        entry: NodeEntry,
        tester: PropertyTester,
    ) -> SparTreeNode | None:
        if entry.parent_path is None or entry.child_index is None:
            return None

        candidate = tree.clone()
        parent = self._node_at_path(candidate, entry.parent_path)
        if parent is None:
            return None

        parent.children = [
            child
            for index, child in enumerate(parent.children)
            if index != entry.child_index
        ]

        source = candidate.to_source()
        if tester.test(source):
            return self.parser.parse(source)
        return None

    def _ddmin_quantified_children(
        self,
        tree: SparTreeNode,
        path: tuple[int, ...],
        tester: PropertyTester,
    ) -> SparTreeNode | None:
        working = tree.clone()
        node = self._node_at_path(working, path)
        if node is None or not node.children:
            return None

        minimum = 1 if node.node_type == NodeType.KLEENE_PLUS else 0
        progress = False
        granularity = 2

        while len(node.children) > minimum:
            partitions = self._split_indices(len(node.children), granularity)
            changed = False

            for chunk in partitions:
                if not chunk:
                    continue
                if len(node.children) - len(chunk) < minimum:
                    continue
                candidate = working.clone()
                candidate_node = self._node_at_path(candidate, path)
                if candidate_node is None:
                    break
                candidate_node.children = [
                    child
                    for index, child in enumerate(candidate_node.children)
                    if index not in chunk
                ]
                source = candidate.to_source()
                if tester.test(source):
                    working = candidate
                    node = self._node_at_path(working, path)
                    granularity = max(granularity - 1, 2)
                    progress = True
                    changed = True
                    break

            if changed:
                continue

            for chunk in partitions:
                if len(chunk) < minimum:
                    continue
                candidate = working.clone()
                candidate_node = self._node_at_path(candidate, path)
                if candidate_node is None:
                    break
                candidate_node.children = [
                    child
                    for index, child in enumerate(candidate_node.children)
                    if index in chunk
                ]
                source = candidate.to_source()
                if tester.test(source):
                    working = candidate
                    node = self._node_at_path(working, path)
                    granularity = 2
                    progress = True
                    changed = True
                    break

            if changed:
                continue

            if granularity >= len(node.children):
                break
            granularity = min(granularity * 2, len(node.children))

        if progress:
            return self.parser.parse(working.to_source())
        return None

    def _replace_with_descendant(
        self,
        tree: SparTreeNode,
        path: tuple[int, ...],
        tester: PropertyTester,
    ) -> SparTreeNode | None:
        node = self._node_at_path(tree, path)
        if node is None:
            return None

        candidates: list[tuple[int, int, tuple[int, ...]]] = []
        for entry in self._walk_entries(node, path):
            if entry.path == path:
                continue
            if entry.node.rule_name != node.rule_name:
                continue
            candidate_size = entry.node.token_count()
            if candidate_size <= 0 or candidate_size >= node.token_count():
                continue
            candidates.append((candidate_size, len(entry.path), entry.path))

        for _, _, candidate_path in sorted(candidates):
            replacement = self._node_at_path(tree, candidate_path)
            if replacement is None:
                continue

            candidate_tree = tree.clone()
            replacement_copy = replacement.clone()

            if not path:
                source = replacement_copy.to_source()
            else:
                parent = self._node_at_path(candidate_tree, path[:-1])
                if parent is None:
                    continue
                parent.children[path[-1]] = replacement_copy
                source = candidate_tree.to_source()

            if tester.test(source):
                return self.parser.parse(source)

        return None

    def _walk_entries(
        self,
        node: SparTreeNode,
        path: tuple[int, ...] = (),
        parent_path: tuple[int, ...] | None = None,
    ) -> list[NodeEntry]:
        entries = [
            NodeEntry(
                path=path,
                parent_path=parent_path,
                child_index=path[-1] if path else None,
                node=node,
            )
        ]

        for index, child in enumerate(node.children):
            if child.deleted:
                continue
            entries.extend(
                self._walk_entries(
                    child,
                    path=path + (index,),
                    parent_path=path,
                )
            )

        return entries

    def _node_at_path(
        self,
        tree: SparTreeNode,
        path: tuple[int, ...],
    ) -> SparTreeNode | None:
        current = tree
        for index in path:
            if index < 0 or index >= len(current.children):
                return None
            current = current.children[index]
        return current

    def _split_indices(self, size: int, partitions: int) -> list[set[int]]:
        if size <= 0:
            return []
        partitions = max(1, min(partitions, size))
        base_size, remainder = divmod(size, partitions)
        chunks: list[set[int]] = []
        start = 0
        for index in range(partitions):
            extra = 1 if index < remainder else 0
            end = start + base_size + extra
            chunks.append(set(range(start, end)))
            start = end
        return chunks

"""Identifier renaming reducer inspired by Vulcan."""

from __future__ import annotations

from collections import Counter

from reduction.grammar import Grammar
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer


class IdentifierReplacementReducer(AbstractReducer):
    """Rename identifiers to shorter names when the property survives."""

    def __init__(self, grammar: Grammar):
        self.grammar = grammar
        self.parser = Parser(grammar)

    @property
    def name(self) -> str:
        return "vulcan_identifier_replacement"

    def reduce(self, tree, tester: PropertyTester):
        current = tree
        progress = True

        while progress:
            progress = False
            identifiers = [
                token.value
                for token in current.tokens()
                if token.type == "IDENTIFIER"
            ]
            if not identifiers:
                break

            frequencies = Counter(identifiers)
            used_names = set(frequencies)
            short_names = self._short_name_stream()

            for identifier, _ in sorted(
                frequencies.items(),
                key=lambda item: (-item[1], len(item[0]), item[0]),
            ):
                if len(identifier) <= 1:
                    continue

                replacement = next(short_names)
                while replacement in used_names or replacement == identifier:
                    replacement = next(short_names)

                candidate = current.clone()
                changed = False
                for token in candidate.tokens():
                    if token.type == "IDENTIFIER" and token.value == identifier:
                        token.value = replacement
                        changed = True

                if not changed:
                    continue

                source = candidate.to_source()
                if tester.test(source):
                    current = self.parser.parse(source)
                    used_names.discard(identifier)
                    used_names.add(replacement)
                    progress = True
                    break

        return current

    def _short_name_stream(self):
        base = [chr(code) for code in range(ord("a"), ord("z") + 1)]
        base.extend(chr(code) for code in range(ord("A"), ord("Z") + 1))
        index = 0
        while True:
            if index < len(base):
                yield base[index]
            else:
                first = base[(index // len(base)) - 1]
                second = base[index % len(base)]
                yield f"{first}{second}"
            index += 1

"""Compatible subtree replacement reducer for Vulcan."""

from __future__ import annotations

from reduction.grammar import Grammar
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree_utils import replace_node_source, walk_entries


class SubtreeReplacementReducer(AbstractReducer):
    """Replace nodes with smaller compatible subtrees from elsewhere in the tree."""

    def __init__(self, grammar: Grammar):
        self.grammar = grammar
        self.parser = Parser(grammar)

    @property
    def name(self) -> str:
        return "vulcan_subtree_replacement"

    def reduce(self, tree, tester: PropertyTester):
        current = tree

        while True:
            progress = False
            entries = [
                entry
                for entry in walk_entries(current)
                if entry.path and entry.node.children
            ]
            entries.sort(key=lambda entry: (-entry.node.token_count(), len(entry.path)))
            source = current.to_source()

            for target in entries:
                candidates = [
                    entry
                    for entry in entries
                    if entry.path != target.path
                    and entry.node.rule_name == target.node.rule_name
                    and entry.node.token_count() < target.node.token_count()
                ]
                candidates.sort(key=lambda entry: (entry.node.token_count(), len(entry.path)))

                for candidate in candidates:
                    replacement_source = candidate.node.to_source()
                    rewritten = replace_node_source(source, target.node, replacement_source)
                    if rewritten == source:
                        continue
                    if tester.test(rewritten):
                        current = self.parser.parse(rewritten)
                        progress = True
                        break

                if progress:
                    break

            if not progress:
                return current

"""Local exhaustive deletion pass for stronger 1-minimality."""

from __future__ import annotations

from itertools import combinations

from reduction.grammar import Grammar
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import NodeType
from reduction.tree_utils import delete_paths, node_at_path, walk_entries


class LocalExhaustiveReducer(AbstractReducer):
    """Try all local deletion patterns within a bounded sliding window."""

    def __init__(
        self,
        grammar: Grammar,
        window_size: int = 3,
        test_budget: int = 200,
    ):
        self.grammar = grammar
        self.parser = Parser(grammar)
        self.window_size = max(1, window_size)
        self.test_budget = max(1, test_budget)

    @property
    def name(self) -> str:
        return "vulcan_local_exhaustive"

    def reduce(self, tree, tester: PropertyTester):
        current = tree
        tests_at_start = tester.test_count

        while tester.test_count - tests_at_start < self.test_budget:
            deletable = self._deletable_entries(current)
            if not deletable:
                return current

            progress = False
            for start in range(len(deletable)):
                window = deletable[start : start + self.window_size]
                if not window:
                    continue

                for pattern in self._pattern_order(window):
                    if tester.test_count - tests_at_start >= self.test_budget:
                        return current

                    candidate_tree = self._delete_pattern(current, [entry.path for entry in pattern])
                    if candidate_tree is None:
                        continue

                    source = candidate_tree.to_source()
                    if tester.test(source):
                        current = self.parser.parse(source)
                        progress = True
                        break

                if progress:
                    break

            if not progress:
                return current

        return current

    def _deletable_entries(self, tree) -> list:
        deletable = []
        blocked_prefixes: set[tuple[int, ...]] = set()

        for entry in walk_entries(tree):
            if not entry.path:
                continue
            if any(entry.path[: len(prefix)] == prefix for prefix in blocked_prefixes):
                continue
            if self._is_whole_node_deletable(tree, entry.path):
                deletable.append(entry)
                blocked_prefixes.add(entry.path)

        return deletable

    def _is_whole_node_deletable(self, tree, path: tuple[int, ...]) -> bool:
        parent = node_at_path(tree, path[:-1])
        node = node_at_path(tree, path)
        if parent is None or node is None:
            return False

        if parent.node_type == NodeType.KLEENE_STAR:
            return True
        if parent.node_type == NodeType.KLEENE_PLUS:
            return len(parent.children) > 1
        if parent.node_type == NodeType.REGULAR and node.node_type in (
            NodeType.OPTIONAL,
            NodeType.KLEENE_STAR,
        ):
            return True
        return False

    def _delete_pattern(self, tree, paths: list[tuple[int, ...]]):
        candidate = delete_paths(tree, paths)
        if candidate is None:
            return None

        for entry in walk_entries(candidate):
            if entry.node.node_type == NodeType.KLEENE_PLUS and not entry.node.children:
                return None
        return candidate

    def _pattern_order(self, window: list):
        size = len(window)
        for width in range(size, 0, -1):
            for indexes in combinations(range(size), width):
                yield [window[index] for index in indexes]

"""Shared SparTree traversal and source-rewrite helpers."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable

from reduction.tree import SparTreeNode


@dataclass(frozen=True)
class TreePathEntry:
    """A tree node paired with its stable path from the root."""

    path: tuple[int, ...]
    parent_path: tuple[int, ...] | None
    child_index: int | None
    node: SparTreeNode


def walk_entries(
    node: SparTreeNode,
    path: tuple[int, ...] = (),
    parent_path: tuple[int, ...] | None = None,
) -> list[TreePathEntry]:
    """Return pre-order entries for every non-deleted node."""
    entries = [
        TreePathEntry(
            path=path,
            parent_path=parent_path,
            child_index=path[-1] if path else None,
            node=node,
        )
    ]

    for index, child in enumerate(node.children):
        if child.deleted:
            continue
        entries.extend(
            walk_entries(
                child,
                path=path + (index,),
                parent_path=path,
            )
        )

    return entries


def node_at_path(tree: SparTreeNode, path: tuple[int, ...]) -> SparTreeNode | None:
    """Resolve ``path`` against ``tree``."""
    current = tree
    for index in path:
        if index < 0 or index >= len(current.children):
            return None
        current = current.children[index]
    return current


def node_line_span(node: SparTreeNode) -> tuple[int, int] | None:
    """Return the inclusive line span covered by ``node``."""
    tokens = node.tokens()
    if not tokens:
        return None

    line_numbers = [token.line for token in tokens]
    return (min(line_numbers), max(line_numbers))


def node_indentation(node: SparTreeNode) -> int:
    """Return the indentation of the first non-empty line in ``node``."""
    for line in node.to_source().splitlines():
        if line.strip():
            return len(line) - len(line.lstrip(" "))
    return 0


def dedent_fragment(fragment: str) -> str:
    """Remove the common leading indentation from ``fragment``."""
    lines = fragment.rstrip("\n").splitlines()
    non_empty = [line for line in lines if line.strip()]
    if not non_empty:
        return ""

    prefix = min(len(line) - len(line.lstrip(" ")) for line in non_empty)
    dedented = [line[prefix:] if line.strip() else "" for line in lines]
    return "\n".join(dedented)


def reindent_fragment(fragment: str, indentation: int) -> str:
    """Reindent ``fragment`` to ``indentation`` spaces."""
    stripped = dedent_fragment(fragment)
    if not stripped:
        return ""

    prefix = " " * max(indentation, 0)
    adjusted = [
        f"{prefix}{line}" if line else ""
        for line in stripped.splitlines()
    ]
    return "\n".join(adjusted) + "\n"


def replace_node_source(
    source: str,
    target_node: SparTreeNode,
    replacement_source: str,
) -> str:
    """Replace the full-line span of ``target_node`` with ``replacement_source``."""
    span = node_line_span(target_node)
    if span is None:
        return source

    start_line, end_line = span
    lines = source.rstrip("\n").splitlines()
    replacement = reindent_fragment(replacement_source, node_indentation(target_node))
    replacement_lines = replacement.rstrip("\n").splitlines()

    new_lines = lines[: start_line - 1] + replacement_lines + lines[end_line:]
    return "\n".join(new_lines).rstrip("\n") + "\n"


def delete_paths(tree: SparTreeNode, paths: Iterable[tuple[int, ...]]) -> SparTreeNode | None:
    """Delete the nodes at ``paths`` from a cloned tree when structurally valid."""
    candidate = tree.clone()
    ordered_paths = sorted(paths, key=lambda path: (len(path), path), reverse=True)

    for path in ordered_paths:
        if not path:
            return None
        parent = node_at_path(candidate, path[:-1])
        if parent is None:
            return None
        if path[-1] < 0 or path[-1] >= len(parent.children):
            return None
        del parent.children[path[-1]]

    return candidate

"""Deterministic mock LLM transformations for LPR."""

from __future__ import annotations

import re

from reduction.tree_utils import dedent_fragment, reindent_fragment


class MockLLM:
    """Regex-driven source-to-source transforms used in place of an LLM."""

    def transform(self, source: str, transformation_type: str) -> str:
        handler = getattr(self, transformation_type, None)
        if handler is None:
            return source
        transformed = handler(source)
        return transformed if transformed else source

    def function_inlining(self, source: str) -> str:
        pattern = re.compile(
            r"^def\s+([A-Za-z_]\w*)\s*\(\s*([^)]*?)\s*\)\s*:\s*\n"
            r"((?:[ ]{4,}[^\n]*\n)+)",
            re.MULTILINE,
        )

        for match in pattern.finditer(source):
            name = match.group(1)
            params = [part.strip() for part in match.group(2).split(",") if part.strip()]
            body = dedent_fragment(match.group(3)).splitlines()
            stripped = [line.strip() for line in body if line.strip()]
            if len(stripped) != 1 or not stripped[0].startswith("return "):
                continue

            expr = stripped[0][len("return ") :]
            source_without_def = source[: match.start()] + source[match.end() :]
            call_pattern = re.compile(rf"\b{re.escape(name)}\s*\(\s*([^()\n]*?)\s*\)")
            changed = False

            def repl(call_match):
                nonlocal changed
                args = [part.strip() for part in call_match.group(1).split(",") if part.strip()]
                if len(args) != len(params):
                    return call_match.group(0)
                inlined = expr
                for param, value in zip(params, args):
                    inlined = re.sub(rf"\b{re.escape(param)}\b", value, inlined)
                changed = True
                return f"( {inlined} )"

            transformed = call_pattern.sub(repl, source_without_def)
            if changed and len(transformed) < len(source):
                return transformed

        return source

    def loop_unrolling(self, source: str) -> str:
        pattern = re.compile(
            r"^([ ]*)for\s+([A-Za-z_]\w*)\s+in\s+range\s*"
            r"\(\s*(\d+)\s*\)\s*:\s*\n((?:\1    [^\n]*\n)+)",
            re.MULTILINE,
        )

        for match in pattern.finditer(source):
            indentation = len(match.group(1))
            variable = match.group(2)
            count = int(match.group(3))
            if count > 4:
                continue

            body = dedent_fragment(match.group(4))
            expanded_parts = []
            for index in range(count):
                expanded = re.sub(rf"\b{re.escape(variable)}\b", str(index), body)
                expanded_parts.append(expanded.rstrip("\n"))

            replacement = ""
            if expanded_parts:
                replacement = reindent_fragment("\n".join(expanded_parts), indentation)

            transformed = source[: match.start()] + replacement + source[match.end() :]
            if len(transformed) < len(source):
                return transformed

        return source

    def variable_elimination(self, source: str) -> str:
        pattern = re.compile(r"(?m)^([ ]*)([A-Za-z_]\w*)\s*=\s*([^\n]+)\n")
        simple_value = re.compile(r"^[A-Za-z0-9_\[\]\{\}\(\)\.,'\" \-\+]+$")

        for match in pattern.finditer(source):
            name = match.group(2)
            value = match.group(3).strip()
            if not simple_value.fullmatch(value):
                continue
            if re.search(rf"\b{re.escape(name)}\b", value):
                continue

            tail = source[match.end() :]
            replaced_tail, count = re.subn(rf"\b{re.escape(name)}\b", value, tail)
            if count == 0:
                continue

            transformed = source[: match.start()] + replaced_tail
            if len(transformed) < len(source):
                return transformed

        return source

    def data_type_elimination(self, source: str) -> str:
        pattern = re.compile(
            r"^class\s+([A-Za-z_]\w*)(?:\s*\([^)]*\))?\s*:\s*\n"
            r"((?:[ ]{4,}[^\n]*\n)+)",
            re.MULTILINE,
        )

        for match in pattern.finditer(source):
            class_name = match.group(1)
            remainder = source[: match.start()] + source[match.end() :]
            if re.search(rf"\b{re.escape(class_name)}\b", remainder):
                continue
            transformed = remainder
            if len(transformed) < len(source):
                return transformed

        return source

    def data_type_simplification(self, source: str) -> str:
        replacements = [
            (re.compile(r"\[\s*([^\[\]\n]+?)\s*\]"), "[]"),
            (re.compile(r"\{\s*([^{}\n]+?)\s*\}"), "{}"),
            (re.compile(r"\(\s*[^()\n]+,\s*[^()\n]+\)"), "()"),
            (re.compile(r"list\s*\([^)\n]*\)"), "[]"),
        ]

        for pattern, replacement in replacements:
            transformed, count = pattern.subn(replacement, source, count=1)
            if count and len(transformed) < len(source):
                return transformed

        return source

"""Reducer wrappers for deterministic mock-LLM transformations."""

from __future__ import annotations

from abc import ABC

from reduction.grammar import Grammar
from reduction.lpr.mock_llm import MockLLM
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import SparTreeNode


class LLMReducer(AbstractReducer, ABC):
    """Base class for regex-backed LPR reducers."""

    transformation_name: str = ""

    def __init__(self, grammar: Grammar, llm: MockLLM | None = None):
        self.grammar = grammar
        self.parser = Parser(grammar)
        self.llm = llm or MockLLM()

    @property
    def name(self) -> str:
        return f"lpr_{self.transformation_name}"

    def reduce(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        source = tree.to_source()
        transformed = self.llm.transform(source, self.transformation_name)
        if transformed == source:
            return tree
        if tester.test(transformed):
            return self.parser.parse(transformed)
        return tree


class FunctionInliningReducer(LLMReducer):
    transformation_name = "function_inlining"


class LoopUnrollingReducer(LLMReducer):
    transformation_name = "loop_unrolling"


class VariableEliminationReducer(LLMReducer):
    transformation_name = "variable_elimination"


class DataTypeEliminationReducer(LLMReducer):
    transformation_name = "data_type_elimination"


class DataTypeSimplificationReducer(LLMReducer):
    transformation_name = "data_type_simplification"

